  "prediction_basis_card_ids": ["C77", "C78", "C83", "C85", "C86", "C52", "C62", "C65"],
  "claims": [
    {
      "claim": "L1 gold records all report oral bioavailability values or qualitative extents above the F>=20% threshold for the reference molecules, but none is the query; they show that steroid-like molecules can be well absorbed but do not resolve the query's first-pass metabolism.",
      "card_ids": ["C01", "C03", "C10", "C12", "C13", "C19", "C22"]
    },
    {
      "claim": "L4 intestinal absorption records for steroid-like molecules show high fraction absorbed (hydrocortisone 89-95% and fa=0.90; prednisolone 95%; corticosterone complete; danazol 100% in dogs), supporting the absorption component for the query.",
      "card_ids": ["C52", "C56", "C58", "C60", "C62", "C63"]
    },
    {
      "claim": "L5 gut-wall records show high passive permeability and no significant efflux for steroid-like molecules (hydrocortisone, budesonide, testosterone), so gut-wall efflux is not an identified barrier for this class.",
      "card_ids": ["C65", "C67", "C71", "C72", "C74", "C75"]
    },
    {
      "claim": "L6 hepatic-clearance records for closely related androgens show substantial hepatic intrinsic clearance: testosterone HLM CLint 353±5 µL/min/mg without BSA and 43±2 with BSA; scaled predicted hepatic clearance 9.7±0.2 mL/min/kg for testosterone and 14.11±0.01 for epitestosterone; 6β-hydroxytestosterone CLint 300 µL/mg/min. These indicate significant hepatic first-pass metabolism in this steroid class.",
      "card_ids": ["C77", "C78", "C83", "C85", "C86"]
    },
    {
      "claim": "The query is a 4-hydroxyandrostenedione steroid; the L6 androgen clearance direction is transferable enough to support substantial presystemic loss, and high absorption/absence of efflux does not overcome it, making F<20% better supported than F>=20%.",
      "card_ids": ["C77", "C83", "C85", "C52", "C65"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "hepatic_clearance_metabolic_stability",
      "applicability": "moderate",
      "direction": "contradictory",
      "decision_effect": "changed",
      "card_ids": ["C77", "C78", "C81", "C83", "C85", "C86"]
    }
  ],
  "evidence_gaps": [
    "No direct oral versus intravenous bioavailability measurement for the query molecule.",
    "L6 records are for testosterone, epitestosterone, and 6β-hydroxytestosterone, not 4-hydroxyandrostenedione; transfer is indirect.",
    "No query-specific gut metabolism or conjugative clearance data.",
    "No query-specific solubility/dissolution measurement; high logP suggests a limitation but is not experimentally established.",
    "Scaled hepatic-clearance predictions (9.7-14.11 mL/min/kg) are moderate; the low prediction depends on combining the androgen clearance direction with the query's 4-hydroxy/17-keto structural features.",
    "No direct evidence of the query's own CYP/UGT substrate status."
  ],
  "decision_summary": "Predicted low (F<20%) because L6 hepatic-clearance records for closely related androgens show substantial first-pass metabolism, and the query's 4-hydroxyandrostenedione structure is consistent with that clearance direction; high absorption and lack of gut-wall efflux do not overcome presystemic loss. Confidence is moderate due to indirect transfer."
}

